moebius = 0.5 + (1.0 - abs( fract( moebius * 0.5 ) * 2.0 - 1.0 )-0.5)*0.99;
ret = texture(sampler_fc_main, moebius );
}
  fragColor = vec4(ret, 1.0);
}

